#!/usr/bin/env bash
# evpn2-ping.sh — spike-evpn2-ping proof body (T093).
# The bridged variant may not disturb the as-built service, and must not
# produce any EVPN MAC/IP signalling. Proof: with the L2VNI attempt stood
# up, the §2 client-to-client probe still passes both directions (the
# as-built encap is untouched), and the EVPN table + MAC table stay EMPTY
# (no Type-2 generated by MAC learning; no overlay forwarding exists).
set -u
. "$(dirname "$0")/spike-env.sh"
bash "$(dirname "$0")/evpn2-setup.sh" >/dev/null 2>&1 || true
c1=$(container_of leaf01)
cl01=$C_srv6_client01; cl02=$C_srv6_client02
echo "===== EVPN table with the L2VNI attempt up (expect exactly the 2 Type-3 IMETs) ====="
node_run "$c1" "vtysh -c 'show bgp l2vpn evpn'" 2>/dev/null | tail -1 || true
echo "===== client01 -> client02 (8900-byte payload DF, as-built §2 path) ====="
client_run "$cl01" "ping -c3 -W3 -s 8900 -M do 192.168.2.2 2>&1 | tail -2" | ping_norm || true
echo "===== client02 -> client01 (8900-byte payload DF) ====="
client_run "$cl02" "ping -c3 -W3 -s 8900 -M do 192.168.1.2 2>&1 | tail -2" | ping_norm || true
echo "===== EVPN MAC table after client traffic (expect no Type-2 learning) ====="
node_run "$c1" "vtysh -c 'show evpn mac vni all' 2>/dev/null | grep -c . | awk '{printf \"MAC-ENTRIES: %s\n\", \$1}'" || true
echo "===== EVPN table after client traffic (still just the 2 Type-3 IMETs) ====="
node_run "$c1" "vtysh -c 'show bgp l2vpn evpn'" 2>/dev/null | tail -1 || true
